shellCommands.command:
cat > /tmp/check-sel.cjs <<'EOF'
const {chromium} = require('/tmp/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({
    executablePath: '/home/node/.cache/ms-playwright/chromium-1254/chrome-linux-arm64/chrome',
    args: ['--no-sandbox'],
  });
  const page = await (await browser.newContext()).newPage();
  await page.goto('http://localhost:5173', {waitUntil: 'networkidle'});
  await page.waitForSelector('.orders-table__row');
  await page.locator('.orders-table__row').nth(0).click();
  await page.locator('.orders-table__row').nth(2).click();
  await page.waitForTimeout(200);
  const info = await page.locator('.orders-table__row').evaluateAll((rows) =>
    rows.slice(0, 5).map((r) => ({
      id: r.querySelector('td:nth-child(2)')?.textContent,
      cls: r.className,
      checked: r.querySelector('input[type=checkbox]')?.checked,
    })),
  );
  console.log(JSON.stringify(info, null, 1));
  await browser.close();
})();
EOF
cd /tmp && export LD_LIBRARY_PATH=$(echo /tmp/debs/root/usr/lib/*/ /tmp/debs/root/lib/*/ | tr ' ' ':') FONTCONFIG_FILE=/tmp/debs/fonts.conf && timeout 90 node check-sel.cjs
